return function(ctx,points,title) local f=require(script.Parent.Parent.Layout.Card)(ctx,UDim2.new(1,0,0,190));local t=Instance.new("TextLabel",f.Instance);t.Size=UDim2.new(1,-20,0,24);t.Position=UDim2.fromOffset(10,8);t.BackgroundTransparency=1;t.Text=title or "Chart";t.TextColor3=ctx.Theme:Get("Text");t.Font=Enum.Font.GothamBold;t.TextSize=14;t.TextXAlignment=Enum.TextXAlignment.Left;local barWidth=(f.Instance.AbsoluteSize.X-20)/math.max(1,#(points or {}));for i,v in ipairs(points or {})do local b=Instance.new("Frame",f.Instance);b.Size=UDim2.fromOffset(math.max(2,barWidth-4),math.clamp(tonumber(v) or 0,4,120));b.Position=UDim2.fromOffset(10+(i-1)*barWidth,170-(tonumber(v) or 0));b.BackgroundColor3=ctx.Theme:Get("Accent");Instance.new("UICorner",b).CornerRadius=UDim.new(0,5)end;return f end
